def extract(b, cells, w):
    arr = np.frombuffer(b, dtype=np.uint8)
    abs_ = np.fromiter((c[1] for c in cells), dtype=np.int64, count=len(cells))
    val = arr[abs_].astype(np.uint64)
    for k in range(1, w):
        val |= arr[abs_ + k].astype(np.uint64) << np.uint64(8 * k)
    return abs_, val


